@import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Manrope:wght@300;400;500;600;700;800&display=swap');

.root {
  --vt-surface: #F4F1DE;
  --vt-surface-2: #FFFFFF;
  --vt-surface-deep: #3D405B;
  --vt-ink: #3D405B;
  --vt-ink-soft: #575A78;
  --vt-on-deep: #F4F1DE;
  --vt-accent: #B54A32;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #B54A32;
  --vt-accent-on-deep: #A8CFBA;
  --vt-line: rgba(61, 64, 91, 0.15);
  --font-heading: 'Lora', Georgia, serif;
  --font-body: 'Manrope', 'Segoe UI', sans-serif;
  --section-pad: clamp(3rem, 6vw, 6rem);
  --gap: clamp(1rem, 2.5vw, 2rem);
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --shadow-card: 0 4px 24px rgba(61, 64, 91, 0.08);
  --shadow-hover: 0 8px 40px rgba(61, 64, 91, 0.14);
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --duration: 0.5s;
  font-family: var(--font-body);
  color: var(--vt-ink);
  background-color: var(--vt-surface);
  line-height: 1.7;
  overflow-x: hidden;
  min-height: 100vh;
  position: relative;
}

.root *,
.root *::before,
.root *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
}

.root a {
  color: inherit;
  text-decoration: none;
}

.root img {
  max-width: 100%;
  display: block;
}

.root ul {
  list-style: none;
}

.root button {
  font-family: var(--font-body);
  cursor: pointer;
  border: none;
  background: none;
}

.navToggle {
  position: absolute;
  opacity: 0;
  pointer-events: none;
  height: 0;
  width: 0;
}

.hamburger {
  display: none;
  position: fixed;
  top: 1rem;
  left: 1rem;
  z-index: 1100;
  width: 48px;
  height: 48px;
  background: var(--vt-surface-deep);
  border-radius: var(--radius-sm);
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-card);
  cursor: pointer;
}

.hamburgerLines {
  width: 22px;
  height: 16px;
  position: relative;
}

.hamburgerLines span {
  display: block;
  position: absolute;
  width: 100%;
  height: 2px;
  background: var(--vt-on-deep);
  border-radius: 2px;
  transition: all 0.3s var(--ease-out);
}

.hamburgerLines span:nth-child(1) {
  top: 0;
}

.hamburgerLines span:nth-child(2) {
  top: 7px;
}

.hamburgerLines span:nth-child(3) {
  top: 14px;
}

.navToggle:checked ~ .hamburger .hamburgerLines span:nth-child(1) {
  top: 7px;
  transform: rotate(45deg);
}

.navToggle:checked ~ .hamburger .hamburgerLines span:nth-child(2) {
  opacity: 0;
}

.navToggle:checked ~ .hamburger .hamburgerLines span:nth-child(3) {
  top: 7px;
  transform: rotate(-45deg);
}

.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  width: 260px;
  height: 100vh;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  display: flex;
  flex-direction: column;
  z-index: 1000;
  overflow-y: auto;
  transition: transform 0.4s var(--ease-out);
  transform: translateX(0);
}

.sidebarBrand {
  padding: 2rem 1.5rem 1.5rem;
  border-bottom: 1px solid color-mix(in srgb, var(--vt-on-deep) 10%, transparent);
}

.sidebarTagline {
  font-size: 0.75rem;
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--vt-accent-on-deep);
  margin-top: 0.35rem;
}

.sidebarNav {
  flex: 1;
  padding: 1.5rem 0;
}

.sidebarNav ul {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sidebarNav a {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: color-mix(in srgb, var(--vt-on-deep) 65%, transparent);
  transition: all 0.3s var(--ease-out);
  position: relative;
  min-height: 44px;
}

.sidebarNav a::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%) scaleY(0);
  width: 3px;
  height: 70%;
  background: var(--vt-accent);
  border-radius: 0 3px 3px 0;
  transition: transform 0.3s var(--ease-out);
}

.sidebarNav a:hover,
.sidebarNav a.active {
  color: var(--vt-on-deep);
  background: color-mix(in srgb, var(--vt-on-deep) 6%, transparent);
}

.sidebarNav a:hover::before,
.sidebarNav a.active::before {
  transform: translateY(-50%) scaleY(1);
}

.navIcon {
  width: 20px;
  text-align: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}

.sidebarFooter {
  padding: 1.5rem;
  border-top: 1px solid color-mix(in srgb, var(--vt-on-deep) 10%, transparent);
}

.sidebarHours {
  font-size: 0.78rem;
  color: color-mix(in srgb, var(--vt-on-deep) 50%, transparent);
  line-height: 1.6;
}

.sidebarHours strong {
  color: var(--vt-accent-on-deep);
  font-weight: 600;
}

.main {
  margin-left: 260px;
  min-height: 100vh;
}

.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: var(--section-pad);
  background:
    radial-gradient(ellipse at 20% 80%, color-mix(in srgb, var(--vt-accent-on-deep) 15%, transparent) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 20%, color-mix(in srgb, var(--vt-accent) 12%, transparent) 0%, transparent 50%),
    var(--vt-surface);
  overflow: hidden;
}

.heroContent {
  max-width: 640px;
  position: relative;
  z-index: 2;
}

.heroTitle {
  font-size: clamp(2.8rem, 6vw, 4.5rem);
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 0.5rem;
  letter-spacing: -0.03em;
}

.heroSubtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--vt-ink-soft);
  margin-bottom: 2rem;
  max-width: 480px;
}

.heroText {
  font-size: 1rem;
  color: var(--vt-ink-soft);
  margin-bottom: 2rem;
  max-width: 480px;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.85rem 1.75rem;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all 0.3s var(--ease-out);
  min-height: 44px;
}

.btnPrimary {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.btnPrimary:hover {
  background: color-mix(in srgb, var(--vt-accent) 85%, black);
  transform: translateY(-2px);
  box-shadow: 0 6px 24px color-mix(in srgb, var(--vt-accent) 35%, transparent);
}

.btnOutline {
  border: 2px solid var(--vt-ink);
  color: var(--vt-ink);
  background: transparent;
}

.btnOutline:hover {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  transform: translateY(-2px);
}

.heroDeco {
  position: absolute;
  right: -2%;
  top: 50%;
  transform: translateY(-50%);
  width: clamp(280px, 35vw, 500px);
  height: clamp(280px, 35vw, 500px);
  z-index: 1;
}

.scoop {
  position: absolute;
  border-radius: 50%;
  box-shadow: inset 0 -10px 30px rgba(0, 0, 0, 0.08), 0 6px 20px rgba(0, 0, 0, 0.06);
}

.scoopStrawberry {
  width: 60%;
  height: 60%;
  background: radial-gradient(circle at 35% 35%, var(--vt-accent), color-mix(in srgb, var(--vt-accent) 70%, black));
  top: 0;
  right: 10%;
}

.scoopMint {
  width: 50%;
  height: 50%;
  background: radial-gradient(circle at 35% 35%, var(--vt-accent-on-deep), color-mix(in srgb, var(--vt-accent-on-deep) 70%, black));
  bottom: 8%;
  right: 0;
}

.scoopVanilla {
  width: 45%;
  height: 45%;
  background: radial-gradient(circle at 35% 35%, var(--vt-surface-2), var(--vt-surface));
  bottom: 15%;
  left: 5%;
}

.scoopHighlight {
  position: absolute;
  width: 25%;
  height: 25%;
  background: rgba(255, 255, 255, 0.5);
  border-radius: 50%;
  top: 15%;
  left: 20%;
  filter: blur(6px);
}

.section {
  padding: var(--section-pad);
}

.sectionAlt {
  background: var(--vt-surface-2);
}

.sectionHeader {
  margin-bottom: clamp(2rem, 4vw, 3.5rem);
}

.sectionLabel {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--vt-accent-ink);
  margin-bottom: 0.75rem;
}

.sectionTitle {
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  color: var(--vt-ink);
  letter-spacing: -0.02em;
}

.sectionDesc {
  margin-top: 0.75rem;
  font-size: 1.05rem;
  color: var(--vt-ink-soft);
  max-width: 560px;
}

.flavorsSection {
  overflow: hidden;
  padding-left: 0;
  padding-right: 0;
}

.flavorsSection .sectionHeader {
  padding-left: var(--section-pad);
  padding-right: var(--section-pad);
}

.marquee {
  position: relative;
  width: 100%;
  overflow: hidden;
  padding: 1rem 0 2rem;
}

.marquee::before,
.marquee::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  width: 80px;
  z-index: 2;
  pointer-events: none;
}

.marquee::before {
  left: 0;
  background: linear-gradient(to right, var(--vt-surface-2), transparent);
}

.marquee::after {
  right: 0;
  background: linear-gradient(to left, var(--vt-surface-2), transparent);
}

.marqueeTrack {
  display: flex;
  width: max-content;
  gap: 1.25rem;
  animation: marquee-scroll 35s linear infinite;
}

.marqueeTrackReverse {
  animation-name: marquee-scroll-reverse;
  animation-duration: 40s;
  margin-top: 1.25rem;
}

.marquee:hover .marqueeTrack {
  animation-play-state: paused;
}

@keyframes marquee-scroll {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%);
  }
}

@keyframes marquee-scroll-reverse {
  0% {
    transform: translateX(-50%);
  }
  100% {
    transform: translateX(0);
  }
}

.flavorCard {
  flex-shrink: 0;
  width: 340px;
  background: var(--vt-surface-2);
  border-radius: var(--radius-lg);
  padding: 1.4rem 1.5rem;
  box-shadow: var(--shadow-card);
  display: flex;
  align-items: center;
  gap: 1.15rem;
  transition: all 0.35s var(--ease-out);
  position: relative;
  overflow: hidden;
  cursor: default;
}

.flavorCard:hover {
  box-shadow: var(--shadow-hover);
  transform: scale(1.03);
}

.flavorCardSwatch {
  width: 62px;
  height: 62px;
  border-radius: 50%;
  flex-shrink: 0;
  position: relative;
  box-shadow: inset 0 -4px 10px rgba(0, 0, 0, 0.08);
  background: radial-gradient(circle at 35% 35%, var(--vt-accent), var(--vt-accent-ink));
}

.flavorCardSwatch::after {
  content: '';
  position: absolute;
  width: 35%;
  height: 35%;
  background: rgba(255, 255, 255, 0.45);
  border-radius: 50%;
  top: 12%;
  left: 18%;
  filter: blur(3px);
}

.flavorCardInfo {
  min-width: 0;
}

.flavorCardType {
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--vt-accent-ink);
  margin-bottom: 0.3rem;
}

.flavorCardName {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 0.15rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.flavorCardDesc {
  font-size: 0.82rem;
  color: var(--vt-ink-soft);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.builder {
  background:
    radial-gradient(ellipse at 70% 30%, color-mix(in srgb, var(--vt-accent) 6%, transparent) 0%, transparent 50%),
    var(--vt-surface-2);
}

.builderLayout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(2rem, 4vw, 4rem);
  align-items: start;
}

.builderSteps {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.builderStep {
  display: flex;
  gap: 1.25rem;
  padding: 1.5rem;
  background: var(--vt-surface);
  border-radius: var(--radius-md);
  transition: all 0.3s var(--ease-out);
}

.builderStep:hover {
  box-shadow: var(--shadow-card);
}

.builderStepNum {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.1rem;
}

.builderStepTitle {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 0.25rem;
}

.builderStepText {
  font-size: 0.88rem;
  color: var(--vt-ink-soft);
}

.builderPreview {
  background: var(--vt-surface);
  border-radius: var(--radius-xl);
  padding: 2.5rem;
  text-align: center;
  position: relative;
  min-height: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.builderPreviewBowl {
  width: 200px;
  height: 110px;
  background: linear-gradient(135deg, var(--vt-surface-deep), var(--vt-ink-soft));
  border-radius: 0 0 50% 50% / 0 0 100% 100%;
  position: relative;
  margin: 0 auto 1.5rem;
}

.builderPreviewBowl::before {
  content: '';
  position: absolute;
  top: -6px;
  left: -10px;
  right: -10px;
  height: 20px;
  background: var(--vt-surface-deep);
  border-radius: 50%;
}

.builderPreviewScoop {
  border-radius: 50%;
  position: absolute;
  box-shadow: inset 0 -6px 15px rgba(0, 0, 0, 0.08);
}

.builderPreviewScoop1 {
  width: 90px;
  height: 90px;
  background: radial-gradient(circle at 35% 35%, var(--vt-accent), var(--vt-accent-ink));
  top: -55px;
  left: 20px;
}

.builderPreviewScoop2 {
  width: 90px;
  height: 90px;
  background: radial-gradient(circle at 35% 35%, var(--vt-accent-on-deep), color-mix(in srgb, var(--vt-accent-on-deep) 70%, black));
  top: -55px;
  right: 20px;
}

.builderPreviewScoop3 {
  width: 80px;
  height: 80px;
  background: radial-gradient(circle at 35% 35%, var(--vt-surface-2), var(--vt-surface));
  top: -90px;
  left: 50%;
  transform: translateX(-50%);
}

.builderPreviewPrice {
  font-size: 2rem;
  font-weight: 800;
  color: var(--vt-accent-ink);
  margin-top: 0.5rem;
}

.footer {
  padding: 3rem var(--section-pad) 2rem;
  background: var(--vt-surface-deep);
  color: color-mix(in srgb, var(--vt-on-deep) 60%, transparent);
}

.footerTop {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid color-mix(in srgb, var(--vt-on-deep) 10%, transparent);
}

.footerBottom {
  padding-top: 1.5rem;
  font-size: 0.78rem;
  text-align: center;
}

.footerBottom a {
  color: var(--vt-accent-on-deep);
}

.btn:focus-visible,
.sidebarNav a:focus-visible,
.hamburger:focus-visible,
.flavorCard:focus-visible {
  outline: 2px solid var(--vt-accent-ink);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@media (max-width: 1024px) {
  .sidebar {
    transform: translateX(-100%);
    width: 280px;
  }
  .navToggle:checked ~ .sidebar {
    transform: translateX(0);
  }
  .hamburger {
    display: flex;
  }
  .main {
    margin-left: 0;
  }
  .builderLayout {
    grid-template-columns: 1fr;
  }
  .heroDeco {
    opacity: 0.3;
    right: -10%;
  }
}

@media (max-width: 640px) {
  .hero {
    padding-top: 5rem;
    min-height: auto;
  }
  .heroDeco {
    opacity: 0.2;
    right: -15%;
    width: 220px;
    height: 220px;
  }
  .section {
    padding-left: 1.25rem;
    padding-right: 1.25rem;
  }
  .flavorsSection {
    padding-left: 0;
    padding-right: 0;
  }
  .flavorsSection .sectionHeader {
    padding-left: 1.25rem;
    padding-right: 1.25rem;
  }
  .marqueeTrack {
    gap: 1rem;
  }
  .flavorCard {
    width: 280px;
  }
  .builderPreview {
    min-height: 300px;
  }
  .footerTop {
    flex-direction: column;
  }
}
